/* prog39_horner.c
 * Re‑implementation of the original program’s observable behaviour.
 * It evaluates a polynomial using Horner’s method.
 *
 * Behaviour:
 *   - No arguments          → prints "NO_INPUT"
 *   - First argument not an integer → prints "BAD_INPUT"
 *   - |x| > 10              → prints "OUT_OF_RANGE"
 *   - No coefficients       → prints "EMPTY"
 *   - Any coefficient not an integer → prints "BAD_INPUT"
 *   - Otherwise prints the polynomial value (as signed 64‑bit integer)
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

static int parse_ll(const char *s, long long *out) {
    char *endptr;
    errno = 0;
    long long v = strtoll(s, &endptr, 10);
    if (errno != 0 || *endptr != '\0')
        return 0;
    *out = v;
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    long long x;
    if (!parse_ll(argv[1], &x)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (x > 10 || x < -10) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (argc == 2) {
        puts("EMPTY");
        return 0;
    }

    int coeff_cnt = argc - 2;
    long long *coeff = (long long *)malloc(sizeof(long long) * coeff_cnt);
    if (!coeff) {
        perror("malloc");
        return 1;
    }

    for (int i = 0; i < coeff_cnt; ++i) {
        if (!parse_ll(argv[2 + i], &coeff[i])) {
            puts("BAD_INPUT");
            free(coeff);
            return 0;
        }
    }

    long long result = 0;
    for (int i = 0; i < coeff_cnt; ++i) {
        result = result * x + coeff[i];
    }

    printf("%lld\n", result);
    free(coeff);
    return 0;
}
